# =================================================================
# CLEANUP: Delete stale core/src/ directory (C4)
# =================================================================

$coreSrc = Join-Path $DeployRoot "core\src"
if (Test-Path $coreSrc) {
    Write-Host "[CLEANUP] Removing stale core/src/ directory..." -ForegroundColor Yellow
    Remove-Item -Recurse -Force $coreSrc
    Write-Host "  [OK] core/src/ deleted" -ForegroundColor Green
} else {
    Write-Host "[CLEANUP] core/src/ not present (already clean)" -ForegroundColor DarkGray
}

# =================================================================
# CLEANUP: Delete stale BP backup files
# =================================================================

$bpBackups = Get-ChildItem -Path $DeployRoot -Recurse -Filter "*.bp*_backup" -ErrorAction SilentlyContinue
if ($bpBackups) {
    foreach ($f in $bpBackups) {
        Remove-Item -Force $f.FullName
        Write-Host "  [DEL] $($f.FullName)" -ForegroundColor DarkGray
    }
    Write-Host "  [OK] BP backup files cleaned" -ForegroundColor Green
} else {
    Write-Host "[CLEANUP] No BP backup files found" -ForegroundColor DarkGray
}

# =================================================================
# BUILD VERIFICATION
# =================================================================

Write-Host "[BUILD] Running zig build..." -ForegroundColor Cyan

$buildOutput = & zig build 2>&1
$buildExit = $LASTEXITCODE

if ($buildExit -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 2 fixes applied" -ForegroundColor Green
    Write-Host ""
    Write-Host "Summary of changes:" -ForegroundColor Cyan
    Write-Host "  C1:  build.zig points to core/nids_main.zig" -ForegroundColor White
    Write-Host "  C2:  nids_main.zig graceful shutdown (no std.os.exit)" -ForegroundColor White
    Write-Host "  C3:  payloadHex return type [max_len * 2]u8" -ForegroundColor White
    Write-Host "  C4:  core/src/ stale directory deleted" -ForegroundColor White
    Write-Host "  H3:  ctrlHandler signals T2-T5 via bridge_init" -ForegroundColor White
    Write-Host "  H5:  wfp_ioctl IOCTL constants via CTL_CODE fn" -ForegroundColor White
    Write-Host "  H6:  wfp_ioctl test block syntax fixed" -ForegroundColor White
    Write-Host "  H8:  nids_main.zig imports bridge_init + calls initAll()" -ForegroundColor White
    Write-Host "  BP228/229/231: Config summary + rule reload + rej counters" -ForegroundColor White
    Write-Host "  FIX: _= on fetchAdd, ANSI escapes verified" -ForegroundColor White
    Write-Host "  M2:  .gitignore updated" -ForegroundColor White
    Write-Host ""
    Write-Host "Suggested git commands:" -ForegroundColor Cyan
    Write-Host "  git add -A" -ForegroundColor White
    Write-Host "  git commit -m "fix: best practices phase 2 - critical/high severity"" -ForegroundColor White
    Write-Host "  git push" -ForegroundColor White
    Write-Host ""

    # Clean up backups on success
    Remove-Item -Recurse -Force $backupDir -ErrorAction SilentlyContinue
} else {
    Write-Host "[BUILD] FAILED (exit code $buildExit)" -ForegroundColor Red
    Write-Host ""
    Write-Host "Build output:" -ForegroundColor Yellow
    Write-Host $buildOutput
    Write-Host ""
    Write-Host "Rolling back all files..." -ForegroundColor Yellow

    Copy-Item (Join-Path $backupDir "core_nids_analyze.zig.bak") Join-Path $DeployRoot "core/nids_analyze.zig" -Force
    Copy-Item (Join-Path $backupDir "core_nids_main.zig.bak") Join-Path $DeployRoot "core/nids_main.zig" -Force
    Copy-Item (Join-Path $backupDir "core_wfp_ioctl.zig.bak") Join-Path $DeployRoot "core/wfp_ioctl.zig" -Force
    Copy-Item (Join-Path $backupDir "build.zig.bak") Join-Path $DeployRoot "build.zig" -Force
    Copy-Item (Join-Path $backupDir ".gitignore.bak") Join-Path $DeployRoot ".gitignore" -Force

    Write-Host "[ROLLBACK] All files restored from backups" -ForegroundColor Yellow
    exit 1
}